const svg=$("#device"),ctlEls={},NS="http://www.w3.org/2000/svg";
function el(t,a,p=svg){const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);p.appendChild(e);return e}
function stxt(s,x,y,sz,fill,anchor="middle",p=svg,w="700"){const t=el("text",{x,y,"font-size":sz,fill,"text-anchor":anchor,"font-family":"system-ui,Arial,sans-serif","font-weight":w,"pointer-events":"none"},p);t.textContent=s;return t}
const KL={};let bezel,modLayer;
function buildPanel(){svg.innerHTML="";
 el("rect",{x:2,y:2,width:696,height:556,rx:22,fill:"#121212",stroke:"#3a3a3a","stroke-width":2});
 stxt("blackbox",350,32,22,"#f2f2f2","middle",svg,"600");stxt("unofficial simulation",36,528,11,"#666","start",svg,"400");
 bezel=el("rect",{x:144,y:44,width:412,height:312,rx:4,fill:"#000",stroke:"#444","stroke-width":2,class:"face"});
 const fo=el("foreignObject",{x:150,y:50,width:400,height:300});const div=document.createElement("div");div.style.cssText="width:100%;height:100%";fo.appendChild(div);
 C.forEach(c=>{const g=el("g",{class:"ctl",tabindex:0,role:"button","aria-label":c.label||KNAMES[+c.id[1]-1]});ctlEls[c.id]=g;
  if(c.t==="btn"){stxt(c.label,c.x,c.y-27,12,"#eee","middle",g);el("circle",{cx:c.x,cy:c.y,r:c.r,fill:"#050505",stroke:"#777","stroke-width":2,class:"face"},g);KL[c.id]=stxt("",c.x,c.y+36,11,"#e879f9","middle",svg,"600")}
  else if(c.t==="knob"){el("circle",{cx:c.x,cy:c.y,r:c.r,fill:"#e9e9e9",stroke:"#999","stroke-width":1.5,class:"face"},g);el("circle",{cx:c.x,cy:c.y,r:c.r-7,fill:"#161616"},g);
   c.ind=el("line",{x1:c.x,y1:c.y,x2:c.x,y2:c.y-c.r+10,stroke:"#fff","stroke-width":3,"stroke-linecap":"round"},g);c.rot=0;KL[c.id]=stxt("",c.x,c.y+c.r+17,12,"#e879f9","middle",svg,"600")}
  else if(c.t==="nav"){el("rect",{x:c.x,y:c.y,width:c.w,height:c.h,rx:4,fill:"#ececec",stroke:"#999","stroke-width":1.5,class:"face"},g);c.lamp=el("rect",{x:c.x+4,y:c.y+c.h-4,width:c.w-8,height:2,fill:"#e879f9",opacity:0},g);stxt(c.label,c.x+c.w/2,c.y+c.h/2+5,13,"#111","middle",g)}
  else{el("rect",{x:c.x,y:c.y,width:c.w,height:c.h,rx:6,fill:"#050505",stroke:"#666","stroke-width":1.5,class:"face"},g);c.lamp=el("circle",{cx:c.x+20,cy:c.y+c.h/2,r:6,fill:"#fff"},g);
   if(c.id==="stop")c.lamp.remove(),c.lamp=el("rect",{x:c.x+14,y:c.y+c.h/2-6,width:12,height:12,fill:"#fff"},g);if(c.id==="play")c.lamp.remove(),c.lamp=el("path",{d:`M${c.x+14} ${c.y+c.h/2-7}l13 7l-13 7z`,fill:"#fff"},g);
   stxt(c.label,c.x+c.w/2+12,c.y+c.h/2+5,14,"#fff","middle",g)}});
 svg.appendChild(fo);initScreen(div);modLayer=el("g",{});bindAll()}
function initScreen(div){cv=document.createElement("canvas");cv.id="screen";cv.width=W*3;cv.height=H*3;X=cv.getContext("2d");div.appendChild(cv);bindScreen()}
const FAM={pads:"pads",wave:"pads",params:"pads",mod:"pads",load:"pads",browse:"pads",keys:"keys",seqs:"seqs",roll:"seqs",seqp:"seqs",song:"song",scene:"song",fx:"fx",fxp:"fx",eq:"fx",mix:"mix",pset:"pset",tools:"tools"};
function refreshPanel(){const fam=S.modFx&&S.scr==="mod"?"fx":FAM[S.scr];C.forEach(c=>{if(c.t==="nav")c.lamp.setAttribute("opacity",fam===c.id?1:0)});
 const blink=performance.now()%600<300,rec=C.find(c=>c.id==="rec"),pl=C.find(c=>c.id==="play");
 rec.lamp.setAttribute("fill",S.recording||S.srec?"#ff3b3b":S.recArm||S.leadIn?(blink?"#ff3b3b":"#552222"):"#fff");pl.lamp.setAttribute("fill",S.playing?"#22c55e":"#fff");
 const s=SCR[S.scr],kk=s.k();["k1","k2","k3","k4"].forEach((id,j)=>{const l=kk[j][0]==="—"?"":kk[j][0];if(KL[id].textContent!==l)KL[id].textContent=l});
 const il=s.i&&s.i!=="—"?"→ "+(s.i.match(/(Waveform|Load|parameter|Modulation|piano roll|scene|band|Mute|Mixer|effect|WAV)/i)||["more"])[0]:"";if(KL.info.textContent!==il)KL.info.textContent=il;
 const bl=S.hist.length||S.ov?"back":"";if(KL.back.textContent!==bl)KL.back.textContent=bl;
 bezel.classList.toggle("tourTarget",!!(tour&&TOURS[tour.i][1][tour.k]&&TOURS[tour.i][1][tour.k][0]==="screen"))}
function drawModDots(){modLayer.innerHTML="";if(!MOD())return;["pads","keys","seqs","fx","mix","tools"].forEach(id=>{const c=C.find(x=>x.id===id);el("circle",{class:"modDot",cx:c.x+c.w-3,cy:c.y+3,r:6},modLayer);stxt("M",c.x+c.w-3,c.y+6.5,8,"#000","middle",modLayer)})}

/* ================= input ================= */
let drag=null,backT=null,tipTimer=null;
// right-click (or long-press on touch) latches a button held down; click it again to let go
const LATCH=new Set();let lpT,skipUp=null;
function toggleLatch(c,held){const g=ctlEls[c.id];if(LATCH.delete(c.id)){g.classList.remove("latched");release(c.id)}else{LATCH.add(c.id);g.classList.add("latched");if(!held)press(c.id)}}
function bindAll(){C.forEach(c=>{const g=ctlEls[c.id];
 g.addEventListener("pointerdown",e=>{e.preventDefault();try{g.setPointerCapture(e.pointerId)}catch(_){}firstGesture();showInfo(c.id);if(e.pointerType!=="mouse"){showTip(c.id,e);clearTimeout(tipTimer);tipTimer=setTimeout(hideTip,2500)}
  if(c.t==="knob"){drag={c,y:e.clientY,acc:0};return}
  if(e.button===2||LATCH.has(c.id)){skipUp=c;toggleLatch(c);return}
  press(c.id);if(e.pointerType!=="mouse")lpT=setTimeout(()=>{skipUp=c;toggleLatch(c,true)},450)});
 g.addEventListener("pointermove",e=>{if(!drag||drag.c!==c)return;drag.acc+=drag.y-e.clientY;drag.y=e.clientY;while(Math.abs(drag.acc)>=7){const d=Math.sign(drag.acc);drag.acc-=d*7;turn(c.id,d)}});
 g.addEventListener("pointerup",()=>{clearTimeout(lpT);if(drag&&drag.c===c){drag=null;return}if(skipUp===c){skipUp=null;return}release(c.id)});
 g.addEventListener("contextmenu",e=>e.preventDefault());g.style.touchAction="none";
 g.addEventListener("wheel",e=>{if(c.t==="knob"){e.preventDefault();turn(c.id,e.deltaY<0?1:-1)}},{passive:false});
 g.addEventListener("pointerenter",e=>{g.classList.add("hl");if(e.pointerType==="mouse")showTip(c.id,e)});g.addEventListener("pointerleave",()=>{g.classList.remove("hl");hideTip()});
 g.addEventListener("mousemove",moveTip);
 g.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();e.stopPropagation();if(c.t!=="knob"){press(c.id);release(c.id)}}else if(c.t==="knob"&&(e.key==="ArrowUp"||e.key==="ArrowDown")){e.preventDefault();turn(c.id,e.key==="ArrowUp"?1:-1)}});
 g.addEventListener("focus",()=>showInfo(c.id))})}
function bindScreen(){let Gd=null;const pt=e=>{const r=cv.getBoundingClientRect();return[(e.clientX-r.left)/r.width*W,(e.clientY-r.top)/r.height*H]};
 const find=(x,y,f)=>{for(let i=R.length-1;i>=0;i--){const r=R[i];if(x>=r.x&&x<r.x+r.w&&y>=r.y&&y<r.y+r.h&&(!f||r[f]))return r}return null};
 const tipOf=r=>r&&r.tip?(typeof r.tip==="function"?r.tip():r.tip):null;
 cv.addEventListener("pointerdown",e=>{e.preventDefault();e.stopPropagation();try{cv.setPointerCapture(e.pointerId)}catch(_){}firstGesture();if(S.sleep){S.sleep=false;return}const[x,y]=pt(e),r=find(x,y,"down")||find(x,y);
  Gd={r,x0:x,y0:y,lx:x,ly:y,tx:0,ty:0,dx:0,dy:0,moved:false};if(r&&r.down)r.down(x,y,Gd);if(e.pointerType!=="mouse"){const t=tipOf(find(x,y,"tip"));if(t){tipHtml(t,e);clearTimeout(tipTimer);tipTimer=setTimeout(hideTip,2500)}}});
 cv.addEventListener("pointermove",e=>{const[x,y]=pt(e);if(Gd){Gd.dx=x-Gd.lx;Gd.dy=y-Gd.ly;Gd.lx=x;Gd.ly=y;Gd.tx=x-Gd.x0;Gd.ty=y-Gd.y0;if(Math.hypot(Gd.tx,Gd.ty)>4)Gd.moved=true;if(Gd.r&&Gd.r.move)Gd.r.move(x,y,Gd);if(e.pointerType!=="mouse")hideTip()}
  else if(e.pointerType==="mouse"){const t=tipOf(find(x,y,"tip"));t?tipHtml(t,e):hideTip()}});
 const up=e=>{if(!Gd)return;const[x,y]=pt(e);if(Gd.r&&Gd.r.up)Gd.r.up(x,y,Gd);Gd=null};cv.addEventListener("pointerup",up);cv.addEventListener("pointercancel",up);cv.addEventListener("pointerleave",e=>{if(e.pointerType==="mouse")hideTip()});
 cv.addEventListener("wheel",e=>{const[x,y]=pt(e),r=find(x,y,"wheel");if(r){e.preventDefault();r.wheel(x,y,e.deltaY)}},{passive:false})}
let gestured=false;
function firstGesture(){if(gestured&&AC&&AC.state==="running")return;gestured=true;if(sound){ensureAC();AC.resume()}}
function press(id){emit("press:"+id);if(S.sleep){S.sleep=false;return}
 if(id==="back"){clearTimeout(backT);backT=setTimeout(()=>{S.sleep=true;stopAll(true);emit("sleep")},3000);back()}
 else if(id==="info"){if(!S.ov&&SCR[S.scr].info)SCR[S.scr].info()}
 else if(NAVS.includes(id))nav(id);else if(id==="play")transportPlay();else if(id==="stop")transportStop();else if(id==="rec")recPress()}
function release(id){if(id==="back")clearTimeout(backT)}
function back(){if(S.ov){S.ov=null;return}if(S.slMenu){S.slMenu=false;return}if(S.hist.length){S.scr=S.hist.pop();emit("scr:"+S.scr)}}
function nav(id){S.ov=null;S.slMenu=false;
 if(id==="keys"&&S.scr==="keys"){S.keys.grid=!S.keys.grid;emit("keys:grid")}else if(id==="keys"){S.scr="keys";S.keys.grid=false}
 else if(id==="fx"&&S.scr==="fx")S.scr="eq";else if(id==="fx"&&S.scr==="eq")S.scr="fx";else if(id==="mix"&&S.scr==="mix")mixCycle();else S.scr=id;
 S.hist=[];emit("scr:"+S.scr)}
function turn(id,d){const c=C.find(x=>x.id===id);c.rot=(c.rot+d*18)%360;c.ind.setAttribute("transform",`rotate(${c.rot} ${c.x} ${c.y})`);if(S.sleep){S.sleep=false;return}
 const o=S.ov;if(o){if(o.t==="val")o.v=clamp(o.v+d,o.min,o.max);else if(o.t==="list")o.sel=clamp(o.sel+d,0,o.items.length-1);return}
 SCR[S.scr].turn&&SCR[S.scr].turn(+id[1]-1,d);emit("knob:"+id);emit("knob")}
const PKEYS={a:0,w:1,s:2,e:3,d:4,f:5,t:6,g:7,y:8,h:9,u:10,j:11,k:12,o:13,l:14,p:15};
document.addEventListener("keydown",e=>{if(e.target.closest&&e.target.closest("input,select,textarea,button,label"))return;if(e.metaKey||e.ctrlKey||e.altKey)return;const k=e.key;
 if(S.ov&&S.ov.t==="kbd"){e.preventDefault();const o=S.ov;if(k==="Enter"){const v=o.val.trim();if(v){S.ov=null;o.enter(v)}}else if(k==="Backspace")o.val=o.val.slice(0,-1);else if(k==="Escape")S.ov=null;else if(k.length===1)o.val=(o.val+k).slice(0,40);return}
 if(S.scr==="keys"&&!S.keys.grid&&PKEYS[k.toLowerCase()]!=null){e.preventDefault();if(!e.repeat){firstGesture();keyOn(Math.floor(S.keys.base/12)*12+PKEYS[k.toLowerCase()])}return}
 if(/^[1-8]$/.test(k)){firstGesture();press(NAVS[+k-1])}else if(k===" "){e.preventDefault();firstGesture();press("play")}else if(k==="."){press("stop")}else if(k==="r"||k==="R"){firstGesture();press("rec")}
 else if(k==="i"||k==="I")press("info");else if(k==="Escape"||k==="Backspace"){e.preventDefault();press("back");release("back")}});
document.addEventListener("keyup",e=>{if(S.scr==="keys"&&PKEYS[e.key.toLowerCase()]!=null)keyUp(Math.floor(S.keys.base/12)*12+PKEYS[e.key.toLowerCase()])});

/* ================= help: tooltips and the info card ================= */
function ctlText(id){const s=SCR[S.scr];if(/^k\d/.test(id)){const j=+id[1]-1,kk=s.k()[j];return[KNAMES[j],kk[0]==="—"?"Does nothing on this screen.":`<b style="display:inline">${kk[0]}</b>: ${kk[1]}`,"knobs: p. 23–25, 70, 84"]}
 const inf=INFO[id];if(id==="info")return[inf[0],inf[1]+`<div class='s'><em>Here:</em> ${s.i}</div>`,inf[2]];if(id==="back")return[inf[0],inf[1]+(s.b&&s.b!=="—"?`<div class='s'><em>Here:</em> ${s.b}</div>`:""),inf[2]];return inf}
function showTip(id,e){const[n,d]=ctlText(id);tipHtml(`<b>${n}</b>${d}${MODTIP[id]&&MOD()?`<div class="m">blackbox-mod: ${MODTIP[id]}</div>`:""}`,e)}
function tipHtml(h,e){const tip=$("#tip");tip.innerHTML=h;tip.hidden=false;moveTip(e)}
function moveTip(e){const tip=$("#tip");if(tip.hidden)return;const w=tip.offsetWidth,h=tip.offsetHeight;let x=e.clientX+14,y=e.clientY+16;if(e.pointerType&&e.pointerType!=="mouse"){x=e.clientX-w/2;y=e.clientY-h-36;if(y<8)y=e.clientY+36}
 if(x+w>innerWidth-8)x=innerWidth-w-8;if(y+h>innerHeight-8)y=e.clientY-h-12;tip.style.left=Math.max(8,x)+"px";tip.style.top=Math.max(8,y)+"px"}
function hideTip(){$("#tip").hidden=true}
const MODTIP={mix:"MIX now cycles Mixer → Mute → Solo.",keys:"The top-right knob picks a chord shape on the Keys screen.",seqs:"Notes added just ahead of the playhead play on that pass; Event PLAY gains 1:2 … 8:8 conditions.",
 fx:"Reverb Type (Plate/Room) and Delay Type (Delay/Munchi) on the effect pages.",tools:"Master compressor models and Comp Thresh on Tools → Main.",pads:"Fidelity machine modes, 24 dB filter, slicer knobs, pad-1 ducker sources."};
const MODN={mix:"MIX (or INFO) cycles Mixer → Mute → <b>Solo</b>. Known issue: un-soloed pads can stay muted; unmute them in Mute mode.",
 wave:"On a Slicer pad: bottom-left knob = slice Start, bottom-right = slice End, top-right = Zoom.",keys:"Top-right knob picks a chord shape (Tri, 7th, 9th, Su2, Su4, 6th, Ad9, Pwr, Oct, Opn, Shl, Qrt, m7, m9, Mj7). In-scale shapes follow the grid's Scale/Root. Chords record into sequences; they need the pad out of Mono.",
 roll:"Event mode: turn PLAY past 100% for conditions 1:2 … 8:8 (play on the A-th of every B loops).",params:"Conf → <b>Fidelity</b> replaces Interp (crunch + SP1200/SP-12/S950/MPC60/SP Raw). The filter becomes 24 dB/oct with drive past noon on Res.",
 mod:"Extra sources EXP1, EXP2, PUMP, LINR fire when pad 1 plays: put a negative Amount on another pad's Level for sidechain pumping.",fxp:"Type comes first. Delay: the stock 7 settings. Munchi (CHOMPI TEMPO granular delay): Wand, Random, Feedback, Freeze, Clock, Width, Duck. Reverb: Plate, or Room with Size, Mod, Early, Width. Munchi and Room are approximations here.",
 tools:"Main page: Compressor is now a list (Off, Stock, Glue, Punch, Opto, Squash, Limit) and Comp Thresh (−24…+12 dB), both right under Headphone. Version shows 3.1.n.",seqs:"Sequencer fix: a note added just ahead of the playhead plays on that pass."};
function showInfo(id){const[n,d,pg]=ctlText(id);$("#info").innerHTML=`<div class="crumb">Control</div><h2>${n}</h2><p>${d}</p>${MODTIP[id]&&MOD()?`<div class="modbox"><b>blackbox-mod:</b> ${MODTIP[id]}</div>`:""}<p class="pg">Manual ${pg}</p>`;infoSig="ctl:"+id+S.scr}
let infoSig="";
function screenSig(){const s=SCR[S.scr];return S.scr+"|"+s.t+"|"+s.k().map(k=>k[0]).join()+"|"+MOD()}
function renderScreenInfo(){const s=SCR[S.scr],kk=s.k();
 $("#info").innerHTML=`<div class="crumb">You are here: <b>${s.path}</b></div><h2>${s.t}</h2><p>${s.d}</p>
 <div class="kmap">${kk.map((k,j)=>`<div><b>${KNAMES[j]}</b>${k[0]==="—"?"—":`${k[0]}: ${k[1]}`}</div>`).join("")}<div class="wide"><b>INFO / BACK</b>INFO: ${s.i} · BACK: ${s.b}</div></div>
 ${MOD()&&MODN[S.scr]?`<div class="modbox"><b>blackbox-mod:</b> ${MODN[S.scr]}</div>`:""}<p class="pg">Manual p. ${s.pg} · hover anything on the screen for what it means</p>`;infoSig=screenSig()}
let lastScr="";
function maybeInfo(){if(S.scr!==lastScr||(infoSig.startsWith(lastScr+"|")&&infoSig!==screenSig())){lastScr=S.scr;if(!infoLock||infoLock!==S.scr)renderScreenInfo();infoLock=null}}
let infoLock=null;
function introInfo(){$("#info").innerHTML=`<h2>Start here</h2><p>This is a working Blackbox. The <b>touchscreen</b> responds to clicks and drags, the <b>knobs</b> to the mouse wheel or dragging, and the buttons below the screen switch between its areas, left to right in the order you'd usually build a track.</p>
 <h3>Try</h3><ul class="tight"><li>Touch some pads. Pink = selected, blue bar = playing.</li><li>Push <b>SEQS</b>, then <b>PLAY</b>: four sequences of the loaded preset play. Touch cells to turn them on and off.</li><li>Push <b>INFO</b> anywhere to dig deeper; <b>BACK</b> returns.</li><li>The pink labels next to the knobs always say what they do on the current screen.</li></ul>
 <p>Pick a <b>guided tour</b> above, or use the chapter list below to jump to any part of the manual.</p>`;infoSig="intro";lastScr=S.scr}
const HISTS={wave:["pads"],params:["pads","wave"],mod:["pads","wave","params"],load:["pads"],browse:["pads","wave"],roll:["seqs"],seqp:["seqs","roll"],scene:["song"],fxp:["fx"]};
function setScr(s){S.ov=null;S.scr=s;S.hist=[...(HISTS[s]||[])];emit("scr:"+s)}
const findPad=f=>{const i=S.pads.findIndex(f);if(i>=0)S.pad=i;return i};
const tb=(rows)=>`<table class="t">${rows.map(r=>`<tr>${r.map((c,j)=>j?`<td>${c}</td>`:`<th>${c}</th>`).join("")}</tr>`).join("")}</table>`;
const CHAP=[
 ["Setting up, outputs and volume","9–11",()=>{setScr("tools");S.toolTab="Main";S.toolRow=0},`<p>The Blackbox runs off a 2 A USB supply and stores everything on the microSD card. There are three stereo outputs plus PHONES; PHONES always carries everything. Outputs are at Eurorack level (±5 V), louder than line level, so turn it down if it distorts.</p><p>Volume lives on <b>TOOLS → Main</b>: top knob picks Headphone or an Out Vol, bottom knob sets it.</p>`],
 ["Overview: the controls","12–13",()=>setScr("pads"),`<p>White buttons choose the area (PADS → KEYS → SEQS → SONG → FX → MIX, then PSET and TOOLS). Black buttons REC, STOP, PLAY run the transport. The screen and the four knobs do everything else; INFO drills in, BACK goes back.</p><p>The black bar at the top shows bar:beat, the recording context (sequence, or scene in Song mode) and a progress bar.</p>`],
 ["Quick start","14–19",()=>{setScr("pset");startTour(0)},`<p>Load a preset from PSET, play pads, look at Keys, play sequences, then songs. The Quick start tour walks through it.</p>`],
 ["Screen navigation map","20",()=>setScr("pads"),`<p>How the screens connect (button → screen, I = INFO, B = BACK):</p>${tb([["PADS","Pads →I Waveform →I Pad Parameters →I Modulation; empty pad →I Load and Record"],["KEYS","Keys ↔ KEYS ↔ Grid"],["SEQS","Sequences →I Piano Roll →I Seq Params (Seq, A–D)"],["SONG","Song Scenes →I Scene Parameters"],["FX","FX →I FX Parameters →I FX Modulation; FX ↔ FX ↔ EQ"],["MIX","Mix ↔ MIX/INFO ↔ Mute"],["PSET / TOOLS","Presets / Tools"]])}`],
 ["Pads and pad modes","21–22",()=>setScr("pads"),`<p>Each pad holds a WAV (or a folder) and has a mode:</p>${tb([["Sample","One-shots and melodies; start/end, loops (forward, bidirectional), reverse. 16-voice pool."],["Multi-sample","A folder spread across the keyboard by root note."],["Clip","Tempo-synced loops; only plays while the clock runs; 2 voices."],["Slicer","Trigger sections of one file; 2 voices."],["Granular","Tiny grains (10–200 ms) for textures; mono."],["New Recording","Clear the pad / record a new WAV."]])}<p>Select a pad, push INFO: empty pads open Load and Record, loaded pads the Waveform screen.</p>`],
 ["The Waveform screen","23–24",()=>{findPad(p=>p.mode==="sample"&&p.w&&!p.multi);setScr("wave")},`<p>Overview on top, zoomable detail below. Pink bracket = Start + Length, white bracket = Loop Start → Loop End (loop points needn't be inside Start/End). Knobs: top = Start/Length, bottom = loop points. The top bar has the pad selector, the Pad Mode selector, the WAV name (touch to change file) and a trigger button.</p>`],
 ["Pad parameters","25, 27–30",()=>{setScr("params");S.ptab="Main"},`<p>Pages: <b>Main</b> (Level, Pitch, Filter, Res, ADSR), <b>Pos</b> (mode-specific), <b>LFO</b>, <b>Conf</b> (Launch, Output, Pan, Poly, Excl Group, MIDI In, Pad Note…).</p><p>Knob pages: tap a knob to move the pink focus frame; the four hardware knobs adjust the four knobs inside it. List pages: top knobs choose the row, bottom knobs the value.</p>${tb([["Launch","Trigger plays through; Gate stops on release; Toggle stops on the next trigger"],["Excl Group","Pads in the same group choke each other"],["Poly Mode","Mono…Poly 8; use the lowest you need"]])}`],
 ["Modulation","26, 30, 98–100",()=>{setScr("params");S.ptab="Main";S.psel=0;S.pfocus=0},`<p>Any parameter with a 3-segment bar can be modulated. Select it, push INFO: three slots of Source + Amount. Sources: LFO, VEL (velocity, on Level by default), PTCH, MODW, MVOL, MPAN or a learned MIDI CC. A CC maps its range to value ± Amount (Filter 20% with 15% amount → 5%…35%). Max 8 CC mappings per pad.</p>`],
 ["Sample pads and loop fade","31–34",()=>{findPad(p=>p.mode==="sample"&&p.w&&!p.multi);setScr("params");S.ptab="Pos"},`<p>Pos page: Loop Mode (None / Forward / Bidirect), Loop Fade, Reverse, Start, Length, Loop Start, Loop End. In Trigger mode a looping sample loops through its release; Gate loops while held; Toggle until the next trigger.</p><p><b>Loop Fade</b> cross-fades the audio just before Loop Start into the end of the loop (a percentage of the loop length) to hide the click. It needs audio before Loop Start to borrow.</p>`],
 ["Multi-sample pads","35–37",()=>{findPad(p=>p.multi);setScr("wave")},`<p>Put the samples for one instrument in their own folder, open the WAV selector, highlight a file in it and choose <b>File → Load All</b>. Files map by their root notes; without root notes they map alphabetically from C2 up (great for drum kits). Limits: 64 WAVs per pad, 80 loaded at once. Only Main, LFO and Conf pages apply.</p>`],
 ["Clip pads","38–41",()=>{findPad(p=>p.mode==="clip");setScr("params");S.ptab="Pos"},`<p>For loops synced to the clock. Clips only play while PLAY is running; touching one before that arms it (white bar). Pos page: Loop, Beat Count (Auto reads an ACID tag or guesses), Quant Size (start/stop on the next boundary) and <b>Sync</b>, which jumps the playback back into line every unit so a clip at a slightly different tempo can't drift.</p><p>Try it: load BB LOFI HIP HOP, start the Keys 90 clip, then change the tempo on the SONG screen.</p>`],
 ["Slicer pads","41–44",()=>{findPad(p=>p.mode==="slicer");setScr("wave")},`<p>Play sections of one file independently. On the Waveform screen touch <b>…</b>: Split adds a slice at the white cursor, Join removes one, Scan detects hits (lower threshold = more slices), Grid divides evenly. Pos page: Slice (which one plays), Slice Seq (Forward, Backwards, Random, Stagger), PlayThru, Loop.</p><p>On KEYS, C2 = slice 1, C#2 = slice 2…; the grid shows numbered slices.</p>`],
 ["Granular pads","45",()=>{findPad(p=>p.mode==="gran");setScr("params");S.ptab="Pos"},`<p>Plays the sample as overlapping grains. Grain Size (≈20 ms–1 s), Density (above 50% grains overlap), Scatter, Speed (100% = original, 0% freezes), Window (how far from the play position grains are picked) and Pan Rnd. More grains = more CPU.</p>`],
 ["Recording samples","46–50",()=>{findPad(p=>!p.w&&!p.multi);setScr("load")},`<p>Select an empty pad, INFO. Set Rec Input (L+R, Left, Right, or <b>Resam</b> = record Out 1 including effects), Gain, Length (Custom = until STOP), Rec Quant, monitoring and threshold. Hold REC and press PLAY. With Lead In on, it counts 4 beats first. New files go to \\Presets\\<i>preset name</i> as RC000001.wav…</p><p>In this simulation L+R uses your microphone (the browser will ask).</p>`],
 ["Trim, clipboard and WAV files","57–61",()=>setScr("pads"),`<p><b>Trim</b>: set the pink bracket on the Waveform screen, then WAV selector → File → Trim (destructive). <b>Clipboard</b>: turn the bottom-right knob on the Pads screen for Cut / Copy / Paste / Clear. File → Delete, Save As, Rename manage files on the card. WAVs can be 16/24/32-bit, mono or stereo, any rate (48 kHz preferred).</p>`],
 ["Keys","62–65",()=>{setScr("keys")},`<p>KEYS plays the selected pad chromatically (C4 = original pitch, or the Root Note). Push KEYS again for the grid: four octaves of one scale, root and scale at the top right. The pad selector (top-left grid) picks the pad, or SEQ to play into the selected sequence. Your computer keyboard plays the piano here (A W S E D F…).</p>`],
 ["Sequences","15, 66–69",()=>setScr("seqs"),`<p>16 cells × 4 patterns (A–D). All patterns of a cell share mode (Pads, Keys, MIDI), target and quantization; each pattern has its own Step Len (1/64 … 8 bars) and Step Count (1–256).</p><p><b>To record</b>: select a cell, go to PADS or KEYS, hold REC and press PLAY, play. REC again stops recording but keeps playing; STOP stops. Recording overdubs. Bottom-right knob on the grid swaps UNDO/CLEAR/OFF for the pattern selector.</p>`],
 ["Piano roll, velocity and probability","70–76",()=>setScr("roll"),`<p>INFO on a sequence. Knobs: top-left select note, top-right length, bottom-left move, bottom-right pitch. Wheel/drag scroll. <b>Event</b> turns the bottom knobs into VEL and PLAY (probability). <b>Edit</b>: Cut, Copy, Paste (adds notes), Clear, Double (copies the pattern into a doubled length), Import (.MID).</p><p>INFO again: Duty Cycle, Quant Size, Step Mode (snap recorded notes), MIDI OUT; and per pattern Step Len / Step Count.</p>`],
 ["Songs, scenes and Keep","77–80",()=>setScr("song"),`<p>Up to 32 scenes. Each fires some pads at its start and plays chosen patterns, repeated Play Count times (M × N). Song button = Song Mode; Loop = off / Loop1 / LoopA. Touching a scene during playback queues it for the next bar.</p><p><b>Keep</b> (new in 3.0) leaves a pad or sequence as it is across a scene change. <b>Grab</b> stores whatever is playing now into the selected scene. Reordering = Add, Cut, Paste.</p>`],
 ["Effects","81–83",()=>setScr("fx"),`<p>Two shared effects, FX1 Delay and FX2 Reverb, fed by per-pad sends (top knobs on the FX screen). Wet signal goes to Out 1. Touch FX1/FX2, INFO for the parameters; INFO again on a knob to modulate it. The reverb is the most CPU-hungry thing on the box.</p>${tb([["Delay","Delay (note value with Beat), Feedback, Cutoff/Width filter, Beat, Filter, Ping"],["Reverb","Decay, Damping, Predelay"]])}`],
 ["EQ","84–85",()=>setScr("eq"),`<p>Push FX twice. A 4-band EQ on the master output: INFO selects a band; knobs set Gain, Frequency, Q and Type (None, L Cut, L Shelf, Param, H Shelf, H Cut). Touch or drag the grid to move the selected point.</p>`],
 ["Mixer and mutes","86",()=>setScr("mix"),`<p>Top knobs = level, bottom knobs = pan of the selected pad. Push MIX again or INFO for Mute mode (green = on, red = muted). Mutes aren't saved with the preset.</p>`],
 ["Presets","18–19, 87–93",()=>setScr("pset"),`<p>A preset holds pads, sequences, scenes, effects and mixer settings. Nothing saves automatically: PSET → Save. File: New, Save As, Rename, Delete, <b>Pack</b> (copy all used WAVs into the preset folder so it can't break), <b>Clean</b> (delete unused WAVs from it). Presets live in \\Presets\\<i>name</i>\\preset.xml.</p>`],
 ["Tools","94–95",()=>setScr("tools"),`<p>Global settings. Main: volumes, brightness, metronome, master compressor, SD mode. Rec: RecToPlay, RecConfig (Global/Per Pad), Lead In. MIDI: Global In, MIDI Seq, PGM In, Pad Record, MIDI Out, USB Dev Out. Clock: Receive, Send, Analog In/Out PPQ.</p>`],
 ["MIDI out: sequences (SEQS)","72–73, 93, 109–111",()=>{const m=S.seqs.findIndex(q=>q.mode==="midi");if(m>=0)S.seq=m;setScr("seqp");S.seqTab="Seq";S.seqRow=3},`<p>All MIDI out comes from sequences, so the MIDI choices live under <b>SEQS</b>:</p>${tb([["SEQS → INFO","Piano roll: the mode button (top left) picks PADS, KEYS or MIDI. A MIDI sequence plays no sound inside the Blackbox, it only sends notes."],["SEQS → INFO → INFO, Seq tab","<b>MIDI OUT</b>: None or Ch1–16, the channel this sequence sends on. Set it to your instrument's channel."],["KEYS → pad selector → SEQ","Keys play into the selected sequence: a MIDI sequence sends them straight out, a Keys sequence plays its pad and sends MIDI on playback."],["Piano roll → Edit → Import","Load a .MID file into the selected pattern; it plays out on the sequence's MIDI OUT channel."]])}<p>To double a pad on an external synth: make a Keys sequence for that pad and give it a MIDI OUT channel. To record from a controller, set TOOLS → MIDI → <b>MIDI Seq</b> to the controller's channel; notes go into the selected Keys/MIDI sequence and through to its MIDI OUT. Show opens the Seq tab (of a MIDI sequence, if the preset has one). The <i>MIDI internal</i> tour walks through it.</p>`],
 ["MIDI in (TOOLS)","96–108",()=>{setScr("tools");S.toolTab="MIDI"},`<p>Global In note map (C4 = 60):</p>${tb([["2–33","Trigger scenes 1–32"],["34 / 35","Previous / next scene"],["36–51","Play pads (bottom-left first)"],["52–67","Toggle sequences"],["68–83","Record into pads (Pad Record on)"],["84–99","Clear pads"],["100–104","Prev pad, next pad, play, record, clear selected"]])}<p>A pad's own MIDI In channel plays it chromatically. MIDI Seq records into Keys/MIDI sequences. MIDI out always comes from sequences. Click <b>MIDI</b> in the toolbar to use a real controller here.</p>`],
 ["Clock and tap tempo","112–114",()=>setScr("song"),`<p>Clock priority: CLOCK IN jack, then MIDI clock (USB or TRS), then the internal clock. PLAY resets to 1:1. On the SONG screen the top-left knob sets the tempo, or tap the tempo box in time.</p>`],
 ["Templates, HighQ and CPU tips","116–118",()=>{setScr("params");S.ptab="Conf"},`<p>A template is a preset whose pads are configured but empty. HighQ interpolation reduces aliasing when playing pads chromatically, at a CPU cost. To avoid crackles: use Mono where you can, avoid the reverb, prefer mono 48 kHz samples, fewer grains.</p>`],
 ["Sleep, firmware and specs","118–121",()=>setScr("tools"),`<p>Hold BACK for 3 s to sleep; any button wakes it (try it here). Firmware: copy blackbox.bin to the card, hold BACK + INFO while plugging in power. Specs: 64 MB RAM cache, samples stream from the card (up to 4 GB), 32 voices total, 24-bit converters.</p>`]];
function chapterShow(i){const[t,pg,fn,html]=CHAP[i];fn();infoLock=S.scr;lastScr="";$("#info").innerHTML=`<div class="crumb">Manual chapter · p. ${pg}</div><h2>${t}</h2>${html}<p><button class="sm" id="scrInfo">What's on this screen?</button></p>`;$("#scrInfo").onclick=renderScreenInfo;
 $("#info").scrollIntoView({behavior:"smooth",block:"nearest"})}

/* ================= blackbox-mod card ================= */
const MODF=[["Solo in the mixer","MIX cycles Mixer → Mute → Solo.",()=>{setScr("mix");S.mixMode="solo"}],["Slicer knobs","Waveform screen of a slicer pad: bottom knobs = slice Start/End, top-right = Zoom.",()=>{findPad(p=>p.mode==="slicer");setScr("wave")}],
 ["Pad-1 ducker","New modulation sources EXP1, EXP2, PUMP, LINR fire when pad 1 plays.",()=>{findPad((p,i)=>i===8);setScr("mod");S.modKey="level";S.modFx=null;S.modRow=2}],["Chords on Keys","Top-right knob on the Keys screen picks a chord shape.",()=>{setScr("keys");S.keys.chord="Tri"}],
 ["Note conditions","Event PLAY gains 1:2 … 8:8.",()=>{setScr("roll");S.roll.ev=true}],["Saturation","Conf page: replaces Overdrive; drives the converter in machine modes.",()=>{findPad(p=>p.mode==="sample"&&p.w&&!p.multi);setScr("params");S.ptab="Conf";S.prow=confKeys(S.pads[S.pad]).indexOf("sat")}],["Fidelity","Conf page: crunch + SP1200, SP-12, S950, MPC60, SP Raw.",()=>{findPad(p=>p.mode==="sample"&&p.w&&!p.multi);setScr("params");S.ptab="Conf";S.prow=confKeys(S.pads[S.pad]).indexOf("interp")}],
 ["24 dB filter","The pad filter is steeper, with drive past noon on Res.",()=>{setScr("params");S.ptab="Main"}],["Compressor models","Tools → Main: Compressor list (Glue, Punch, Opto, Squash, Limit) and Comp Thresh.",()=>{setScr("tools");S.toolTab="Main";S.toolRow=1}],
 ["Reverb / Delay Type","Plate or Room; Delay or Munchi.",()=>{setScr("fxp");S.fxSel=1}]];
function renderModCard(){const c=$("#modCard");c.hidden=!MOD();if(!MOD())return;c.innerHTML=`<h2 style="color:var(--mod)">blackbox-mod 3.1.n layer</h2><p class="pg">Community firmware mod for the original Blackbox, built on stock 3.1.9 (this manual covers 3.0). Not from 1010music. Amber M markers show affected buttons.</p>
 <p class="pg">Video walkthrough by the mod's author: <a href="https://www.youtube.com/watch?v=XQJCY2Asl0s" target="_blank" rel="noopener">The Blackbox OG Just Got SP-1200 Mode, Chords and Sidechain</a>. Each feature has a guided tour (Guided tours → Mod: …).</p>
 <ul class="chap">${MODF.map((m,i)=>`<li><span><b>${m[0]}</b> ${m[1]}</span><button data-m="${i}">Show</button></li>`).join("")}</ul>
 <details><summary>Not shown, and known issues</summary><ul class="tight"><li>Munchi is approximated: a tempo delay that feeds the reverb (Wand right), jumps its time at random (Wand left) and freezes; no reverse/octave glitches, no Duck. Room ignores Mod.</li><li>Solo can stick: pads may stay muted after un-soloing.</li><li>Chords need the pad out of Mono.</li><li>Install: patch your own BLACKBOX.bin 3.1.9, then BACK + INFO at power-on. Keep the stock file to go back.</li></ul></details>`;
 c.querySelectorAll("button[data-m]").forEach(b=>b.onclick=()=>{MODF[+b.dataset.m][2]();lastScr=""})}

