let tour=null;
const MODVID="https://www.youtube.com/watch?v=XQJCY2Asl0s&t=";
function startTour(i){const o=TOURS[i][2]||{};if(o.mod&&!MOD())$("#modBtn").click();tour={i,k:0};renderTour()}
function renderTour(){document.querySelectorAll(".ctl.tourTarget").forEach(e=>e.classList.remove("tourTarget"));const box=$("#tourBox");if(!tour){box.hidden=true;return}
 const[name,steps,o={}]=TOURS[tour.i];box.hidden=false;const vid=o.v!=null?`<p class="pg"><a href="${MODVID}${o.v}s" target="_blank" rel="noopener">Watch this part of Justin Joe's mod video (${Math.floor(o.v/60)}:${String(o.v%60).padStart(2,"0")})</a></p>`:"";
 if(tour.k>=steps.length){box.innerHTML=`<h2>${name}</h2><p class="done">Done.</p><div class="nav"><button id="tClose">Close</button></div>`;$("#tClose").onclick=()=>{tour=null;renderTour();$("#tourSel").value=""};return}
 const[target,text]=steps[tour.k];if(ctlEls[target])ctlEls[target].classList.add("tourTarget");
 box.innerHTML=`<h2>${name}</h2><p class="pg">Step ${tour.k+1} of ${steps.length}</p><p class="step">${text}</p>${vid}<div class="nav"><button id="tPrev">Back</button><button id="tNext">Skip</button><button id="tClose">Close</button></div>`;
 $("#tPrev").onclick=()=>{tour.k=Math.max(0,tour.k-1);renderTour()};$("#tNext").onclick=()=>{tour.k++;renderTour()};$("#tClose").onclick=()=>{tour=null;renderTour();$("#tourSel").value=""}}
function emit(ev){if(!tour)return;const st=TOURS[tour.i][1][tour.k];if(st&&(st[2]===ev||(st[2]==="knob"&&ev.startsWith("knob"))||(st[2].endsWith("*")&&ev.startsWith(st[2].slice(0,-1))))){tour.k++;setTimeout(renderTour,200)}}

