function PD(id,o={}){const e=LIB.get(id),p=newPad();Object.assign(p,{w:id,name:e.n,root:e.root||0,start:0,len:e.buf.length,ls:0,le:e.buf.length});const{n,mods,...rest}=o;Object.assign(p,rest);
 if(p.mode==="slicer"&&!o.slices)p.slices=gridSlices(e.buf,n||8);if(p.mode==="clip"&&!o.launch)p.launch="Toggle";if(mods)p.mods={...p.mods,...mods};return p}
function MULTIP(folder,o={}){const p=newPad();const fs=[...LIB.values()].filter(e=>e.f===folder).sort((a,b)=>a.root-b.root);p.multi=fs.map(e=>({id:e.id,root:e.root}));Object.assign(p,{w:fs[0].id,name:folder.split("\\").pop(),len:fs[0].buf.length,le:fs[0].buf.length},o);return p}
const dp=(pad,str,v=110)=>[...str].flatMap((c,i)=>c==="x"?[{t:i,p:pad,len:1,v,prob:100}]:c==="o"?[{t:i,p:pad,len:1,v:Math.round(v*.55),prob:100}]:[]);
const kn=a=>a.map(([t,p,len=1,v=100,prob=100])=>({t,p,len,v,prob}));
function SQ(mode,pats,o={}){const s=newSeq();s.mode=mode;Object.assign(s,o);pats.forEach((pt,k)=>{if(pt)s.pats[k]={len:pt.len||"1/16",steps:pt.steps||16,notes:pt.notes}});return s}
function SCN(name,seqs,pads,count){const s=newScene();Object.assign(s,{name,seqs,pads:pads||{},count:count||1});return s}
