function presetNames(){return[...new Set([...Object.keys(FACTORY),...Object.keys(userPresets())])].sort()}
function userPresets(){try{return JSON.parse(localStorage.getItem("bbx.presets")||"{}")}catch(_){return{}}}
function storeUser(u){try{localStorage.setItem("bbx.presets",JSON.stringify(u))}catch(_){toast("Couldn't save (storage blocked)")}}
function storeTools(){try{localStorage.setItem("bbx.tools",JSON.stringify(TOOLS))}catch(_){}}
function savePreset(name){const u=userPresets();u[name]={name,bpm:S.bpm,swing:S.swing,songMode:S.songMode,loop:S.loop,recp:S.recp,fx:S.fx,eq:S.eq,scenes:S.scenes,
 pads:S.pads.map(p=>{const q={...p};delete q._wz;delete q._ss;delete q._st;return q}),seqs:S.seqs.map(({run,start,pending,nextPat,loop,...q})=>q)};storeUser(u);S.dirty=false}
function applyPreset(P){if(AC)stopAll(true);const keepKeys=S?S.keys:null;S=Object.assign(UI0(),P);if(keepKeys)S.keys={...keepKeys,held:new Map()};
 S.pads=P.pads.map(p=>({...newPad(),...p}));S.seqs=P.seqs.map(q=>({...newSeq(),...q,run:false,pending:null}));sceneNo=Math.max(0,...S.scenes.map(s=>s.num||0));
 S.fx={...newFX(),...P.fx,d:{...newFX().d,...P.fx.d},r:{...newFX().r,...P.fx.r}};S.recp={...newRecP(),...(P.recp||{})};BC.clear();applyAll();S.psetSel=Math.max(0,presetNames().indexOf(S.name));lastScr=""}
function loadPreset(name){let P;if(userPresets()[name])P=JSON.parse(JSON.stringify(userPresets()[name]));else if(FACTORY[name]){const f=FACTORY[name](),bp=blankPreset(name);
  Object.entries(f.pads).forEach(([i,p])=>bp.pads[i]=p);Object.entries(f.seqs).forEach(([i,q])=>bp.seqs[i]=q);(f.active||[]).forEach(i=>bp.seqs[i].active=true);
  sceneNo=0;P={...bp,bpm:f.bpm,swing:f.swing,songMode:f.songMode,loop:f.loop,scenes:f.scenes};}else return;
 applyPreset(P);S.scr="pads"}

/* ================= MIDI input ================= */
async function midiInit(){try{const acc=await navigator.requestMIDIAccess();const hook=()=>{MIDIO=[...acc.outputs.values()];acc.inputs.forEach(i=>i.onmidimessage=onMidi)};hook();acc.onstatechange=hook;
  $("#midiBtn").setAttribute("aria-pressed","true");emit("midi:on");toast(`MIDI: ${acc.inputs.size} in, ${acc.outputs.size} out`)}catch(e){toast("Web MIDI isn't available in this browser",2500)}}
const mp=k=>(3-Math.floor(k/4))*4+k%4; // Global In maps pads/sequences from the bottom-left
function onMidi(e){const[st,d1,d2=0]=e.data,typ=st&0xf0,ch="Ch"+((st&15)+1);if(!AC)return;
 if(typ===0x90&&d2>0)emit("midi:note");else if(typ===0xB0||typ===0xE0)emit("midi:cc");
 if(typ===0xB0){const key=`CC ${(st&15)+1}:${d1}`;S.midi.cc[key]=d2;if(d1===1)S.midi.mw=d2/127;if(d1===7)S.midi.vol=d2/127;if(d1===10)S.midi.pan=d2/63.5-1;
  if(S.learn&&S.scr==="mod"){const T=SCR.mod.tgt(),sl=T.slots(S.modKey),j=Math.floor(S.modRow/2);sl[j][0]=key;if(!sl[j][1])sl[j][1]=50;S.learn=false;T.changed(S.modKey);toast("Learned "+key)}return}
 if(typ===0xE0){S.midi.pb=((d2<<7|d1)-8192)/8192;return}
 if(typ===0xC0){if(TOOLS.pgmIn==="ON"){const L=presetNames();if(L[d1])loadPreset(L[d1])}return}
 const on=typ===0x90&&d2>0,off=typ===0x80||(typ===0x90&&d2===0);if(!on&&!off)return;const vel=d2/127;let used=false;
 S.pads.forEach((p,i)=>{if(p.midiIn===ch){used=true;if(on){play(i,{note:d1,key:d1,vel});recHit("key",i,d1,vel)}else{keyOff(i,d1);recRelease(d1)}}});
 if(TOOLS.midiSeq===ch){used=true;const sq=S.seqs[S.seq];if(on){if(sq.mode==="keys"){play(sq.pad,{note:d1,key:d1,vel});recHit("key",sq.pad,d1,vel)}else if(sq.mode==="midi"){midiNote(sq.midiOut,d1,vel,AC.currentTime,.25);recHit("key",null,d1,vel)}}else{if(sq.mode==="keys")keyOff(sq.pad,d1);recRelease(d1)}}
 const gi=TOOLS.globalIn;if(!(gi===ch||(gi==="Omni"&&!used)))return;if(on)globalNote(d1,vel)}
function globalNote(n,vel){const pn=S.pads.findIndex(p=>p.padNote===n);if(pn>=0){play(pn,{vel});recHit("pad",pn,null,vel);return}
 const queue=()=>{if(S.playing&&S.songMode&&S.song)S.song.queued=S.scene};
 if(n>=2&&n<=33){if(S.scenes[n-2]){S.scene=n-2;queue()}return}if(n===34||n===35){S.scene=clamp(S.scene+(n===34?-1:1),0,S.scenes.length-1);queue();return}
 if(n>=36&&n<=51){const i=mp(n-36);play(i,{vel});recHit("pad",i,null,vel);return}if(n>=52&&n<=67){S.seq=mp(n-52);toggleSeq(S.seq);return}
 if(TOOLS.padRec!=="ON"||S.srec&&!(n>=68&&n<=83||n===103))return;
 const recTo=i=>{S.pad=i;if(S.srec){recFinish();return}if(S.pads[i].w||S.pads[i].multi){toast("Pad must be empty to record");return}S.scr="load";S.hist=["pads"];S.recArm=true;transportPlay()};
 const clr=i=>{S.pad=i;Object.assign(S.pads[i],{w:null,multi:null,name:""});S.scr="pads"};
 if(n>=68&&n<=83)recTo(mp(n-68));else if(n>=84&&n<=99)clr(mp(n-84));else if(n===100)S.pad=Math.max(0,S.pad-1);else if(n===101)S.pad=Math.min(15,S.pad+1);else if(n===102)play(S.pad,{vel});else if(n===103)recTo(S.pad);else if(n===104)clr(S.pad)}

